/**
 * Typed wrapper around the wasm-pack output.
 *
 * `src/wasm/` is generated by `pnpm wasm` (gitignored), so the interface is
 * hand-written here instead of importing the generated types.
 */
import init, {
    bocf_latex,
    families,
    fs_term,
    lngi_step,
    milestones,
    ordinal_value,
    dbms as triangular,
    one_y,
    parse,
    start_ms,
    veblen_latex,
    zero_y,
} from '../wasm/btbm_core.js';

/** Result of the computation step: canonical plain form + progress. */
export interface LngiStep {
    ordinal: string;
    percent: number;
}

/** Display modes: how the ordinal is *structured* (format is a separate flag). */
export type DisplayMode =
    | 'index'
    | 'layer'
    | 'annotated'
    | 'bocf'
    | 'veblen'
    | 'zeroy'
    | 'dbms'
    | 'y1';

/**
 * The available structures. Formatting is orthogonal (`renderOrdinal`'s `latex`
 * flag): the superscript in `(0)(1^(2))` is a real `<sup>` by default, or a
 * `^{...}` group when LaTeX output is requested.
 */
export const DISPLAY_MODES: { id: DisplayMode; label: string; labelZh?: string }[] = [
    { id: 'layer', label: 'BTBMS (Layer)', labelZh: '标记父项 BTBMS' },
    { id: 'index', label: 'BTBMS (Index)', labelZh: '标记距离 BTBMS' },
    { id: 'annotated', label: 'BTBMS (Annotated)', labelZh: '显示距离 BTBMS' },
    // BOCF keeps going past EBO as an idea, but this conversion stops there.
    { id: 'bocf', label: 'BOCF (before EBO)', labelZh: 'BOCF（EBO 之前）' },
    { id: 'veblen', label: 'Veblen' },
    { id: 'zeroy', label: '0-Y' },
    // DBMS and 1-Y/ω-Y stop at SHO. The notations themselves carry on past it,
    // but nothing here can turn a BTBMS term into them, so the labels say where
    // the conversion ends rather than where the notation does.
    { id: 'dbms', label: 'DBMS (before SHO)', labelZh: 'DBMS（SHO 之前）' },
    { id: 'y1', label: '1-Y/ω-Y (before SHO)', labelZh: '1-Y/ω-Y（SHO 之前）' },
];

export let START_MS = 0;

/** Load the wasm module (called once at app startup). */
export async function initWasm(): Promise<void> {
    await init();
    START_MS = start_ms();
}

/**
 * Compute the ordinal at `elapsedMs`.
 *
 * Mode-independent: the result is the canonical plain form, so rendering is a
 * separate on-demand step ([`renderOrdinal`]) that never recomputes it.
 */
/**
 * The `index`-th fundamental-sequence term of an ordinal, in plain form.
 *
 * `null` when the ordinal is a successor (nothing to expand) or cannot be
 * parsed.
 */
export function fsTerm(plain: string, index: number): string | null {
    return fs_term(plain, index) ?? null;
}

/**
 * The fundamental sequence of the notation's limit: `family(1)`, `family(2)`, …
 *
 * The limit itself has no finite expression, so the tree is rooted at a
 * synthetic `LIMIT` whose children are these.
 */
export function familyChain(count: number): string[] {
    return JSON.parse(families(count)) as string[];
}

/** The value at which an ordinal first appears (`null` if it never does). */
export function ordinalValue(plain: string): number | null {
    return ordinal_value(plain) ?? null;
}

/** One entry of the generated milestone table. */
export interface MilestoneRow {
    ordinal: string;
    title: string;
    desc: string;
    value: number;
    atMs: number;
}

/** The milestone table (generated at build time). */
export function milestoneRows(): MilestoneRow[] {
    // `null` stands in for infinity (JSON has no such literal); `LIMIT` uses it
    // for both its value and its arrival time.
    const raw = JSON.parse(milestones()) as {
        ordinal: string;
        title: string;
        desc: string;
        value: number | null;
        atMs: number | null;
    }[];
    return raw.map((row) => ({
        ...row,
        value: row.value ?? Number.POSITIVE_INFINITY,
        atMs: row.atMs ?? Number.POSITIVE_INFINITY,
    }));
}

export function lngiStep(elapsedMs: number): LngiStep {
    return lngi_step(elapsedMs) as LngiStep;
}

/**
 * Render a plain-form ordinal in `mode`; `latex` selects LaTeX vs. HTML.
 *
 * `maxColumns` caps the number of rendered columns (`0` = no cap); the rest are
 * replaced by an ellipsis. Display-only — the ordinal is untouched.
 */
/**
 * The ordinal in Buchholz OCF form, as LaTeX.
 *
 * `null` means the ordinal is past what the notation reaches (or too wide to be
 * worth converting); the caller must show the ordinary BTBMS form instead.
 */
export function bocfLatex(plain: string): string | null {
    return bocf_latex(plain) ?? null;
}

/**
 * The ordinal as an extended Veblen expression, as LaTeX.
 *
 * `null` from the Bachmann–Howard ordinal up, where no Veblen normal form
 * exists; the caller falls back to BOCF, then to the ordinary BTBMS form.
 */
export function veblenLatex(plain: string): string | null {
    return veblen_latex(plain) ?? null;
}

/**
 * The ordinal as a 0-Y sequence, e.g. `1,2,4,8`.
 *
 * `null` once a column carries a nested height, which 0-Y cannot express; the
 * caller falls back to the ordinary BTBMS form.
 */
export function zeroY(plain: string): string | null {
    return zero_y(plain) ?? null;
}

/** The ordinal as triangular BMS, e.g. `(0)(1,1)(2,2,2)`; `null` likewise. */
export function dbms(plain: string): string | null {
    return triangular(plain) ?? null;
}

/** The ordinal as a 1-Y / ω-Y sequence, or `null` once it is past SHO. */
export function oneY(plain: string): string | null {
    return one_y(plain) ?? null;
}

export function renderOrdinal(
    plain: string,
    mode: DisplayMode,
    latex: boolean,
    maxColumns: number,
): string {
    return parse(plain, mode, latex, maxColumns);
}
